import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"周易阐真 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"周易阐真 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/029.md","filePath":"zh/classics/chanzhen/029.md"}'),s={name:"zh/classics/chanzhen/029.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大过，大者过也。栋挠，本末弱也。刚过而中，巽而说，行。利有攸往，乃亨。大过之时大矣哉！</p></blockquote><h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><p>初六：藉用白茅。无咎。</p><p>九二：枯杨生稊，老夫得其女妻，无不利。</p><p>九三：栋桡，凶。</p><p>九四：栋隆，吉。有它，吝。</p><p>九五：枯杨生华，老妇得其士夫，无咎无誉。</p><p>上六：过涉灭顶，凶，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：泽灭木，大过。君子以独立不惧，遁世无闷。</p><p>大过者，大之过也。上兑泽，下巽木，泽性下润，木性上升。泽上于木，反能灭木；木下于泽，反能泽灭，此大过之象也。</p><p>君子有见于此，知泽之浸润大过，能灭其木；人之才智大过，能伤其德。以是法泽上于木，独立而不惧；木下于泽，遁藏而无闷；立大过人之志，成大过人之德焉。盖以修道君子，以性命为一大事，俯视一切，万有皆空。如泽之清，尘缘不染，借世法而修道法，独弦绝调，生死不变，立乎万物之上而不惧；如木之柔，有才不恃，有智不用，被褐怀玉，韬明养晦，不求人知，隐遁深藏而无闷。不惧者，万物难屈，志气大过乎人；无闷者，妄念不生，修养大过乎人。惟其不惧无闷，故能成世间稀有之事，而为人人之所不能识不能及也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>桡，音闹。稊，音提。它，汤何反。</p><p>大过者，阳气有过也。卦德上兑悦，下巽入，巽于内而悦于外，顺其所欲，乐极生悲。卦体内四阳而外二阴，阳过于阴，阴不及阳，故谓大过。此调和药物，实必用虚之卦，承上大畜而来。大畜者，健而能止，止健正，所以养健，不使阳气太过耳。</p><p>金丹之道，取二八两弦之气，凝结成胎，须要大小无伤，两国俱全。若阳气太盛，阴气太弱，阴阳不调，失其生生之道，阴极必败，阳极必亏，栋桡摧折之患，势所必有，栋至摧折，大厦尽倾。</p><p>修道者，进阳太过，不知止足，能大而不能小，神室有伤，亦如此类。若能巽进而不至于过猛，和缓而不至于固执，通权达变，防危虑险，则刚柔相应，阴阳相济，虽大而能不过，可以利有攸往，尽性至命，亨通而无阻滞矣。</p><p>初六，性质本柔，又居卑下，柔之太过，谨慎之至，如藉用白茅，而不敢先人，傲气悉化，自无过大之咎。此小而不妨太过者也。</p><p>九二，刚而能柔，阳太过而借阴以济之，过而不过，如枯杨生稊，老夫得其女妻，阴阳相当，生机常存，刚而不伤，自无不利。此用柔而刚不过者也。</p><p>九三，以刚用刚，只知前进，不知后退，金丹得而复失，栋桡之凶，所不能免。此用刚而太于过者也。</p><p>九四，大而能小，心平气和，如栋隆不败，动与吉会矣。修道至于大而能小，已是阴阳相合，再不可过于用柔，若用柔太过，又伤于刚，大道难成，遗笑于大方，适以取吝而己。此刚而用柔不可过者也。</p><p>九五，刚于悦而不能柔以悦，如枯杨生华，老妇得其士夫，过于淫奢，自满自足，阳极生阴，真为假伤，理有可决。幸其刚而得中，内有主宰，不为客气所惑，得以无咎。既已实腹，不能虚心，中道而止，却亦无誉。此刚而持盈之大过者也。</p><p>上六，在大过之终，愚而自用，不知药物火候，任心造作，迷而不返，升之高，伤之甚，过涉灭顶，自招其凶，与人无咎。此柔而妄想之大过者也。</p><p>观于六爻之义，大过者凶，不过者吉。大过之中，亦有不过之道。是在人善于调和阴阳，归于中正，不偏不倚为贵欤。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
